/// PLIC Interrupt Source Peripheral.
///
/// Enumeration used to determine which peripheral asserted the corresponding
/// interrupt.
#[derive(Copy, Clone, PartialEq, Eq)]
#[repr(u32)]
pub enum PlicPeripheral {
    /// Unknown Peripheral
    Unknown = 0,
    /// uart0
    Uart0 = 1,
    /// uart1
    Uart1 = 2,
    /// uart2
    Uart2 = 3,
    /// uart3
    Uart3 = 4,
    /// gpio0
    Gpio0 = 5,
    /// gpio1
    Gpio1 = 6,
    /// spi_device
    SpiDevice = 7,
    /// i2c0
    I2c0 = 8,
    /// i2c1
    I2c1 = 9,
    /// i2c2
    I2c2 = 10,
    /// i3c0
    I3c0 = 11,
    /// i3c1
    I3c1 = 12,
    /// rv_timer
    RvTimer = 13,
    /// otp_ctrl
    OtpCtrl = 14,
    /// alert_handler
    AlertHandler = 15,
    /// spi_host0
    SpiHost0 = 16,
    /// spi_host1
    SpiHost1 = 17,
    /// usbdev
    Usbdev = 18,
    /// pwrmgr
    Pwrmgr = 19,
    /// sysrst_ctrl
    SysrstCtrl = 20,
    /// adc_ctrl
    AdcCtrl = 21,
    /// aon_timer
    AonTimer = 22,
    /// sensor_ctrl
    SensorCtrl = 23,
    /// rram_ctrl
    RramCtrl = 24,
    /// hmac
    Hmac = 25,
    /// kmac
    Kmac = 26,
    /// otbn
    Otbn = 27,
    /// keymgr_dpe
    KeymgrDpe = 28,
    /// csrng
    Csrng = 29,
    /// entropy_src
    EntropySrc = 30,
    /// edn0
    Edn0 = 31,
    /// edn1
    Edn1 = 32,
    /// cheriot_mem_sys
    CheriotMemSys = 33,
}

impl TryFrom<u32> for PlicPeripheral {
    type Error = u32;
    fn try_from(val: u32) -> Result<Self, Self::Error> {
        match val {
            0 => Ok(Self::Unknown),
            1 => Ok(Self::Uart0),
            2 => Ok(Self::Uart1),
            3 => Ok(Self::Uart2),
            4 => Ok(Self::Uart3),
            5 => Ok(Self::Gpio0),
            6 => Ok(Self::Gpio1),
            7 => Ok(Self::SpiDevice),
            8 => Ok(Self::I2c0),
            9 => Ok(Self::I2c1),
            10 => Ok(Self::I2c2),
            11 => Ok(Self::I3c0),
            12 => Ok(Self::I3c1),
            13 => Ok(Self::RvTimer),
            14 => Ok(Self::OtpCtrl),
            15 => Ok(Self::AlertHandler),
            16 => Ok(Self::SpiHost0),
            17 => Ok(Self::SpiHost1),
            18 => Ok(Self::Usbdev),
            19 => Ok(Self::Pwrmgr),
            20 => Ok(Self::SysrstCtrl),
            21 => Ok(Self::AdcCtrl),
            22 => Ok(Self::AonTimer),
            23 => Ok(Self::SensorCtrl),
            24 => Ok(Self::RramCtrl),
            25 => Ok(Self::Hmac),
            26 => Ok(Self::Kmac),
            27 => Ok(Self::Otbn),
            28 => Ok(Self::KeymgrDpe),
            29 => Ok(Self::Csrng),
            30 => Ok(Self::EntropySrc),
            31 => Ok(Self::Edn0),
            32 => Ok(Self::Edn1),
            33 => Ok(Self::CheriotMemSys),
            _ => Err(val),
        }
    }
}

